#!/usr/bin/env node
// Regenerates packages/shared/src/generated from the Rust engine's types (ts-rs) and writes an
// index barrel. The engine is the source of truth for every profile/schedule/override/pool type
// and for the policy model; never edit the generated files by hand. Run with `pnpm gen:types`.

import { execFileSync } from 'node:child_process';
import { readdirSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outDir = path.join(root, 'packages/shared/src/generated');

rmSync(outDir, { recursive: true, force: true });
execFileSync(
  'cargo',
  ['test', '--quiet', '--manifest-path', 'native/engine/Cargo.toml', '--features', 'ts', '--lib', 'export_bindings'],
  { cwd: root, stdio: 'inherit' },
);

const types = readdirSync(outDir)
  .filter((file) => file.endsWith('.ts') && file !== 'index.ts')
  .map((file) => file.slice(0, -3))
  .sort();
const index =
  '// Generated by scripts/generate-engine-types.mjs from native/engine (ts-rs). Do not edit.\n' +
  types.map((type) => `export type { ${type} } from './${type}';`).join('\n') +
  '\n';
writeFileSync(path.join(outDir, 'index.ts'), index);
console.log(`wrote ${types.length} engine types to packages/shared/src/generated`);
